  b1Ep12BlankInstruction: "Complète la phrase.",
  b1Ep12BlankHint: "Trois mots : « Would it be... »",
  b1Ep12OpenInstruction: "Demande une solution au problème.",
  b1Ep12OpenInstruction2: "Maintenant, négocie une autre solution — sans aide cette fois.",
  b1Ep13Title: "Garder son calme",
