  b1Ep13CompOptWrong2: "C'est bon, ne t'en fais pas.",
  b1Ep13BlankInstruction: "Complète la phrase.",
  b1Ep13BlankHint: "Trois mots : « This isn't... »",
  b1Ep13OpenInstruction: "Montre ce que tu ressens à ce sujet — poliment.",
  b1Ep13OpenInstruction2: "Encore une fois — sans aide cette fois.",
