  b1RetryExplainFrustrationMarker: "Tu as nommé le problème, mais pas ce que tu ressens — essaie « this isn't ideal, but... ».",
  b1RetryPromptFrustrationMarker: "Ajoute « this isn't ideal, but... » ou « I understand, but... ».",
