  b1PraiseNegotiateIndependent: "Super — une vraie négociation, polie.",
  b1PraiseNegotiateHelped: "Bien joué — ça demande poliment une solution.",
  b1RetryExplainNegotiateSpeechAct: "Ça, c'est une offre d'acheter quelque chose de neuf, pas une demande de solution — essaie « would it be possible to... ».",
