  b1RetryExplainNegotiateUnderdeveloped: "Bon début — transforme-le maintenant en une demande complète et polie, comme « would it be possible to... » ou « could I possibly... ».",
  b1RetryPromptNegotiateFrame: "Essaie « would it be possible to... » ou « could I possibly... ».",
  b1Ep15Title: "Quel est le programme",
