  b1Ep16ComprehensionInstruction: "Quelle phrase exprime un espoir sans date précise, et non un projet pour la semaine prochaine ?",
  b1Ep16CompOptCorrect: "J'espère voyager davantage un jour.",
  b1Ep16CompOptWrong1: "Je vais voyager le mois prochain.",
