  b2PraiseFrustrationIndependent: "Great — you expressed frustration without losing diplomacy.",
  b2PraiseHypothesisHelped: "Nice — you used the hypothetical form correctly.",
  b2PraiseHypothesisIndependent: "Great — a real unreal-conditional hypothesis.",
  b2PraiseJustifyHelped: "Nice — you explained why, then asked.",
  b2PraiseJustifyIndependent: "Great — a clear request, with a real reason.",
  b2PraiseOpinionHelped: "Nice — you gave an opinion and a reason.",
  b2PraiseOpinionIndependent: "Great — a real opinion, with your own reason.",
  b2PraiseProposeHelped: "Nice — you proposed a way to resolve it.",
  b2PraiseProposeIndependent: "Great — a clear, workable proposal.",
  b2PraiseReformulateHelped: "Nice — that's clearer than the original.",
